// ---------------------------------------------------------------------------
// sections.generated.ts — generated by nvoos-astro-forge (Proposal 117 §2);
// edits are overwritten on re-scaffold. The source band theming: each entry
// keys the source Elementor section id to its background facts and the
// resolved rebuild theme. The DesignRenderer matches rebuilt sections by id
// and wraps them accordingly. Deterministic: same profile, same bytes.
// ---------------------------------------------------------------------------

export type SectionThemeName = 'hero' | 'dark' | 'alt' | 'light';

/** One measured typography fact (a heading level or the body paragraph), from
 * the source's COMPUTED styles (`analyze --geometry`). */
export interface BandTypeFact {
	size?: string;
	weight?: string;
	lineHeight?: string;
	letterSpacing?: string;
	transform?: string;
	align?: string;
	/** What the source CHANGES below the desktop breakpoint (and only that). */
	tablet?: BandTypeProperties;
	mobile?: BandTypeProperties;
}

/** A BandTypeFact without its own device overrides. */
export type BandTypeProperties = Omit<BandTypeFact, 'tablet' | 'mobile'>;

export type BandSpacing = 'template' | 'source';

/** Whether a band with no source padding fact keeps the template rhythm
 * or renders flush (the source’s own 0). From profile.bandSpacing. */
export const bandSpacing: BandSpacing = 'template';

/** Where the band list came from. `outline` = no Elementor ids exist, so the
 * renderer maps bands POSITIONALLY (section index → band index). */
export const bandSource: 'sections' | 'outline' = 'sections';

export interface SectionTheme {
	id?: string;
	theme: SectionThemeName;
	/** The source section anchor (the chrome nav links to it). */
	anchor?: string;
	/** The source band background (gradient or flat color). */
	bg?: string;
	/** The hero photo (hero sections only). */
	bgImage?: string;
	/** The overlay tint over the hero photo. */
	overlay?: string;
	/** The source band padding (the declared padding fact). */
	padding?: string;
	/** The band's MEASURED source height — a CSS min-height FLOOR, never a lock. */
	minHeight?: string | { desktop?: string; tablet?: string; mobile?: string };
	/** The band's measured TYPOGRAPHY; `title` is its LARGEST heading. */
	type?: { headings?: Record<string, BandTypeFact>; body?: BandTypeFact; title?: BandTypeFact };
	/** Selectors for subtrees the SOURCE renders hidden at rest — emitted as
	 * scoped `display:none` rules. */
	hidden?: string[];
	/** The builder's presentation utilities this band uses, with their
	 * device-scoped variants. */
	utilities?: Record<string, { base?: string; tablet?: string; mobile?: string }>;
	/** The MEASURED box (padding/margin/cropped-media height) of the classes
	 * this band keeps, per device. The builder spacing scale is not a ladder, so
	 * these are computed values re-stated verbatim. Emitted AFTER `utilities`, so
	 * a measured value outranks a hand-authored approximation. */
	box?: Record<string, { base?: string; tablet?: string; mobile?: string }>;
	/** Cropped-media heights, emitted as `img.<class>` only. */
	media?: Record<string, { base?: string; tablet?: string; mobile?: string }>;
	/** The band's measured COLUMN geometry, keyed by the column's unique class:
	 * a rendered `min-height` floor plus a fixed background photo's attachment
	 * and size. Emitted as band-scoped `.class` rules (the sanitizer keeps the
	 * class but drops the inline layout, and the vendor sheet never ships). */
	columnBox?: Record<string, { base?: string; tablet?: string; mobile?: string }>;
	/** The boxed container width (the source constrains its content —
	 * jayainc's Elementor 1140px default). Absent → the site measure. A
	 * per-device map is emitted as scoped CSS: an inline value would
	 * outrank its own media queries. */
	measure?: string | { desktop?: string; tablet?: string; mobile?: string };
	/** The container side gutter (the source's own padding, measured per
	 * device). Absent → the template clamp. */
	paddingX?: string | { desktop?: string; tablet?: string; mobile?: string };
	/** Section-level pull facts (124 §4) — negative margins overlap
	 * the neighbor band; z-index stacks the overlap. */
	marginTop?: string | { desktop?: string; tablet?: string; mobile?: string };
	marginBottom?: string | { desktop?: string; tablet?: string; mobile?: string };
	zIndex?: string;
	/** The top-level column responsive facts (124 §6) — widths per
	 * device + order/visibility; the split components re-measure. */
	columns?: Array<{
		width?: number;
		widthTablet?: number;
		widthMobile?: number;
		reverseMobile?: boolean;
		reverseTablet?: boolean;
		hiddenMobile?: boolean;
		hiddenTablet?: boolean;
		hiddenDesktop?: boolean;
	}>;
	/** The content rhythm (125 §1) — 'split' = a copy column beside a
	 * media collage column (the source's two-column hero bands). */
	layout?: 'split';
	/** The heading's underline divider facts (width/height/background/shadow). */
	titleDivider?: { width: string; height: string; background: string; shadow?: string };
	/** The heading typography (size/weight/line-height/letter-spacing). */
	titleStyle?: { size?: string; weight?: string; lineHeight?: string; letterSpacing?: string };
	/** The heading is centered (the source's aux-widget-inner centering). */
	titleAlign?: 'center';
	/** The media collage backdrop shape (width/height/background/radius). */
	mediaShape?: { width: string; height: string; background: string; radius?: string };
	/** The card box model of a media grid band (measured — see lib/types). */
	cardStyle?: { gap?: string; padding?: string; textPadding?: string };
	/** Per-image collage offsets (absolute positioning against the collage box). */
	mediaOffsets?: Array<{ top?: string; right?: string; bottom?: string; left?: string; shadow?: string }>;
	/** The body paragraphs render in N columns (the source's sub-column split). */
	bodyColumns?: number;
	/** The band's flipbook catalog (125 §4) — the PDF the sanitizer
	 * would otherwise lose with the dflip script; the rebuild renders
	 * a titled open-catalogue CTA. */
	catalog?: { title?: string; source: string };
}

export const sections: SectionTheme[] = [];
